insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('00755628-cce5-47af-babe-3fa106a44cb6', '935dba97-3b82-406d-a424-ac9c44293f89', $$inleiding: export eieren weggevallen; vraag- en aanbodvergelijkingen eiermarkt$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context1.png$$,
   $$In het land Ovaria is de uitvoer van eieren volledig weggevallen door een internationaal conflict. De afzet van eieren is daardoor sterk gekrompen. De overheid verwacht dat deze situatie nog jaren zal duren. Economen hebben de ontstane situatie op de eiermarkt in dit land weergegeven met onderstaande vergelijkingen van vraag en aanbod per maand. Eieren worden hier als een homogeen product beschouwd.
Qₐ = 4P − 120 | Qₐ = aangeboden hoeveelheid eieren in miljoenen kilo''s
Qᵥ = −2P + 240 | Qᵥ = gevraagde hoeveelheid eieren in miljoenen kilo''s
P = prijs per kilo eieren in coins (de munteenheid van het land)$$, 'inline'),
  ('b5154f0a-e535-4349-93df-2f1ee86b5664', '935dba97-3b82-406d-a424-ac9c44293f89', $$marktprijs 60 coin per kilo; lijnen A, V₀ en V₁ in figuur 1$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context2.png$$,
   $$In de ontstane situatie is de marktprijs 60 coin per kilo. Deze marktsituatie is in figuur 1 weergegeven met de lijnen A en V₁. De lijn V₀ is de oorspronkelijke vraaglijn voordat de export wegviel. De aanbodlijn is niet veranderd. Het gedrag van de vragers in het binnenland is niet veranderd.$$, 'inline'),
  ('51f1307d-238f-40b7-acd9-405e535b3fe4', '935dba97-3b82-406d-a424-ac9c44293f89', $$eierboer De Haan: constante kosten 140.000 coin, variabele kosten 40 coin per kilo, capaciteit 4.000 kilo$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context3.png$$,
   $$Een eierboer in dit land, de heer De Haan, heeft 140.000 coin constante kosten per maand. De variabele kosten zijn proportioneel en bedragen
40 coin per kilo eieren. Zijn productiecapaciteit bedraagt 4.000 kilo eieren per maand. De Haan streeft naar maximale totale winst. Bij de marktprijs van 60 coin lijdt hij echter verlies.$$, 'inline'),
  ('72a706fd-2a4e-4b99-ac02-188695f8f321', '935dba97-3b82-406d-a424-ac9c44293f89', $$overheid overweegt minimumprijs met aankoopgarantie overschot$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context4.png$$,
   $$Met het wegvallen van de export overweegt de overheid om een minimumprijs in te stellen, met de garantie aan de boeren dat ze het ontstane overschot aan eieren zal aankopen. Aangekochte eieren zullen worden vernietigd.$$, 'inline'),
  ('5da84891-efea-4dd5-98d3-f31f7fb6a689', '935dba97-3b82-406d-a424-ac9c44293f89', $$minimumprijs van 80 coin per kilo$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context5.png$$,
   $$De overheid besluit tot een minimumprijs van 80 coin per kilo eieren. Dit zal het totale consumenten- en producentensurplus veranderen.$$, 'inline'),
  ('15a2cda0-9640-44f7-a46c-025af4ba5f0f', '935dba97-3b82-406d-a424-ac9c44293f89', $$figuur 1: markt van eieren in Ovaria (A, V₀, V₁, Pₘᵢₙ, vlakken B-G)$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context6.png$$,
   $$figuur 1 Markt van eieren in Ovaria
P in coins (0-120) tegen Qₐ en Qᵥ in miljoenen kilo''s (0-300); aanbodlijn A, vraaglijnen V₀ en V₁, minimumprijs Pₘᵢₙ op 80; gearceerde vlakken B, C, D, E, F en G
A = aanbod van eieren
V₀ = vraag naar eieren in de oorspronkelijke situatie
V₁ = vraag naar eieren na het wegvallen van de export
Pₘᵢₙ = minimumprijs, ingesteld door de overheid$$, 'inline'),
  ('d952a8dc-5073-415e-a5f8-ada2b07862dc', '935dba97-3b82-406d-a424-ac9c44293f89', $$kosten overheid overtreffen toename totaal surplus$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-context7.png$$,
   $$De kosten die de overheid moet maken zullen volgens de economen de toename van het totale consumenten- en producentensurplus echter overtreffen.$$, 'inline'),
  ('dc319fd3-7f13-4089-8f6e-16fb71b4db7d', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$inleiding: Abec verkoopt 1,5 miljoen auto's, 62,8 kilo restafval per auto; Mission Zero$$,
   $$economie-vwo-2016-ii-mission-zero-context1.png$$,
   $$In 2011 verkoopt autoproducent Abec 1,5 miljoen auto’s. De productie gaat in 2011 gepaard met veel restafval: 62,8 kilo per auto. Het management wil dat Abec zich maatschappelijk gaat profileren met een ‘groen’ imago en schrijft een plan: Mission Zero. Doelstelling in Mission Zero is een reductie van het restafval tot bijna nul in het jaar 2022, zonder dat daarbij de productiekosten per auto stijgen.$$, 'inline'),
  ('bf55714b-2421-4313-ab63-1e18bf85914d', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$twee stappen in Mission Zero: nieuwe technieken en verkoop restafval aan recyclingbedrijf$$,
   $$economie-vwo-2016-ii-mission-zero-context2.png$$,
   $$In Mission Zero worden de volgende twee stappen beschreven:
1 De ontwikkeling en introductie van nieuwe technieken, waardoor grondstoffen efficiënter worden ingezet en er minder restafval per auto wordt geproduceerd;
2 Het restafval wordt in de periode tot 2022 doorverkocht aan een recyclingbedrijf dat het verwerkt tot herbruikbare grondstoffen voor de productielijnen van Abec of voor andere industrieën.$$, 'inline'),
  ('24700305-7231-4643-98b8-596563473113', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$onderzoek naar stap 1: figuur 1 en bron 1$$,
   $$economie-vwo-2016-ii-mission-zero-context3.png$$,
   $$Het management van Abec laat eerst onderzoek doen naar de uitvoering van stap 1. Informatie uit dit onderzoek staat weergegeven in figuur 1 en bron 1.$$, 'inline'),
  ('38c78607-3bee-487d-9678-6f69fe684add', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$figuur 1: prognose restafval per auto bij stap 1 (2011-2022)$$,
   $$economie-vwo-2016-ii-mission-zero-context4.png$$,
   $$figuur 1 Prognose restafval van de productie per auto bij stap 1 (in kilo''s)
2011: 62,8
2012: 49,7
2013: 39,1
2014: 37,5
2015: 32,4
2016: 30,7
2017: 28,1
2018: 24,7
2019: 20,3
2020: 8,1
2021: 4,1
2022: 1,8$$, 'inline'),
  ('a6da41e8-0d7b-4aae-9f3a-224827976efb', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$bron 1: actuele gegevens en verwachtingen met Mission Zero (kostenopbouw en veranderingen)$$,
   $$economie-vwo-2016-ii-mission-zero-context5.png$$,
   $$bron 1 Actuele gegevens en verwachtingen met Mission Zero
gegevens over 2011:
− de gemiddelde totale kosten bestaan voor 50% uit gemiddelde constante kosten
− de gemiddelde variabele kosten bestaan voor 10% uit kosten die te maken hebben met het restafval
verwachte veranderingen voor 2022 ten opzichte van 2011:
− een toename van de totale constante kosten van 15%
− een toename van de gemiddelde variabele kosten die niet te maken hebben met restafval met 21%, als gevolg van het gebruik van duurzame, recyclebare materialen
− een afname van de gemiddelde variabele kosten die wél te maken hebben met het restafval, evenredig met de afname van het restafval
− een groei van de afzet van auto´s van 19%$$, 'inline'),
  ('fa538f69-79d8-4b3e-b2c3-82920597d0c0', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$management concludeert dat kosten per auto stijgen; stap 2 essentieel$$,
   $$economie-vwo-2016-ii-mission-zero-context6.png$$,
   $$Op basis van deze informatie concludeert het management dat met stap 1 de kosten per auto naar verwachting toch zullen toenemen. Het management beschouwt het daarom als essentieel dat ook stap 2 wordt uitgevoerd.$$, 'inline'),
  ('e8f4335a-7957-4c93-ba99-e0239a8bdec7', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$TRF huiverig voor omvangrijke investering in verwerkingsinstallatie$$,
   $$economie-vwo-2016-ii-mission-zero-context7.png$$,
   $$Abec verzoekt afvalverwerkingsbedrijf The Recycling Factory (TRF) om een offerte op te stellen voor het kopen en recycleren van het restafval in de periode tot het jaar 2022. TRF ziet hier wel winstmogelijkheden, maar zal hiervoor een omvangrijke investering moeten doen in een aangepaste verwerkingsinstallatie en is daarom toch huiverig om deze stap te zetten.$$, 'inline'),
  ('1c117f2e-543e-4878-9eae-6b6c3d0be854', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$Abec stelt voor aandelen in TRF te kopen$$,
   $$economie-vwo-2016-ii-mission-zero-context8.png$$,
   $$Om TRF het nodige vertrouwen te geven, doet de directie van Abec het voorstel om kapitaal voor deze investering beschikbaar te stellen door aandelen in TRF te kopen.$$, 'inline'),
  ('67cef41a-cabc-4f8f-abc4-d3ae3f1c1d59', 'b0bcae07-5d14-446e-bcda-7c2e3df38fc3', $$De Groene Planeet vreest toename negatieve externe effecten$$,
   $$economie-vwo-2016-ii-mission-zero-context9.png$$,
   $$Milieuorganisatie De Groene Planeet verwacht dat het initiatief van Abec snel gevolgd zal worden door concurrerende autoproducenten. De organisatie is bezorgd dat deze trend van ‘vergroening’ ook zal leiden tot een toename van negatieve externe effecten, in de verwachting dat mensen juist meer auto’s zullen aanschaffen, aangelokt door het imago van milieuvriendelijkheid.$$, 'inline'),
  ('0d76dbbb-9a51-4172-965e-1423a64af699', 'c663373e-bf29-442a-b4e0-32945a5f9237', $$inleiding: belastingconcurrentie tussen overheden als gevangenendilemma$$,
   $$economie-vwo-2016-ii-belastingopbrengsten-op-de-tocht-context1.png$$,
   $$Multinationale ondernemingen moeten in principe in alle landen waar ze gevestigd zijn winstbelasting betalen. Overheden kunnen geneigd zijn om dergelijke bedrijven te lokken met lagere tarieven voor de winstbelasting, om de eigen economie te stimuleren. Een econoom beargumenteert de stelling dat bij deze vorm van ‘belastingconcurrentie’ overheden in een positie komen die kan worden beschouwd als een gevangenendilemma, ervan uitgaande dat deze hun totale belastingopbrengsten op peil willen houden.$$, 'inline'),
  ('e33c0287-288b-47f0-a2a2-8246aa039850', 'c663373e-bf29-442a-b4e0-32945a5f9237', $$multinationals dreigen met verplaatsing; Alagne, Belanië en Cervoland$$,
   $$economie-vwo-2016-ii-belastingopbrengsten-op-de-tocht-context2.png$$,
   $$Multinationale ondernemingen hebben, naast het hoofdkantoor in hun ‘thuisland’, productiebedrijven in andere landen. Met de dreiging om deze vestigingen te verplaatsen naar een ander land kunnen zij overheden onder druk zetten om voor hen apart lagere tarieven voor de winstbelasting te rekenen. Met name in ontwikkelingslanden hebben deze ‘multinationals’ een sterke positie ten opzichte van de nationale overheden. In tabel 1 is Alagne een sterk industrieland. Belanië kan gezien worden als een land met een opkomende economie en Cervoland als een ontwikkelingsland.$$, 'inline'),
  ('3ccd86ae-6193-483e-89fe-4005ea1654bb', 'c663373e-bf29-442a-b4e0-32945a5f9237', $$tabel 1: kerngegevens over productie en belasting in drie landen$$,
   $$economie-vwo-2016-ii-belastingopbrengsten-op-de-tocht-context3.png$$,
   $$tabel 1 Kerngegevens over productie en belasting in drie landen waar multinationals zijn gevestigd
| (1) bruto binnenlands product in euro''s | (2) totale productiewaarde van de voornaamste lokaal gevestigde multinationals in euro''s | (3) tarief van winstbelasting
Alagne | 625 mld. | 10 mld. | 22%
Belanië | 1.200 mld. | 6 mld. | 25%
Cervoland | 200 mld. | 5 mld. | 24%$$, 'inline'),
  ('2b507bbb-3ebc-4587-82ce-825c9275eaa6', 'c663373e-bf29-442a-b4e0-32945a5f9237', $$argumenten voor winstbelastingverdragen; dubbele belastingheffing$$,
   $$economie-vwo-2016-ii-belastingopbrengsten-op-de-tocht-context4.png$$,
   $$Niet alleen vanuit het belang van overheden maar ook vanuit het oogpunt van multinationals zijn er argumenten die pleiten voor het instellen van winstbelastingverdragen. Multinationals zijn bijvoorbeeld gebaat bij een verdrag ter voorkoming van dubbele belastingheffing in situaties waarbij vanuit de productiebedrijven winsten worden overgeboekt naar het hoofdkantoor.$$, 'inline'),
  ('b5ce5a28-3928-4514-979a-fbd99525707e', 'c663373e-bf29-442a-b4e0-32945a5f9237', $$winstbelastingverdrag: winst belast waar verdiend tegen laagste tarief; EMNO$$,
   $$economie-vwo-2016-ii-belastingopbrengsten-op-de-tocht-context5.png$$,
   $$De overheden van Alagne, Belanië en Cervoland hebben een winstbelastingverdrag met elkaar afgesloten. Hierin is afgesproken dat winsten alleen worden belast in het land waar deze zijn verdiend, tegen het laagste tarief dat in de verdragslanden geldt. De multinationale onderneming EMNO heeft het hoofdkantoor gevestigd in Alagne en een winstgevend productiebedrijf in Cervoland. Dankzij het verdrag behoeft EMNO over de winst van deze vestiging alleen aan de overheid van Cervoland winstbelasting te betalen, tegen een tarief van slechts 22%.$$, 'inline'),
  ('12f7483e-771f-4b05-a14c-5782a0ec8039', 'c663373e-bf29-442a-b4e0-32945a5f9237', $$multinationals kunnen ook hoofdkantoor verplaatsen$$,
   $$economie-vwo-2016-ii-belastingopbrengsten-op-de-tocht-context6.png$$,
   $$Nieuwe ontwikkelingen, zoals op het gebied van informatietechnologie, hebben het denkbaar gemaakt dat multinationals kunnen overwegen om ook (delen van) het hoofdkantoor naar een ander land te verplaatsen.$$, 'inline'),
  ('091bc54b-8d02-4809-82c2-f9c6e9f06390', 'a01516ce-4b7d-45f1-93a7-df774feb3a94', $$inleiding: Deense overheid overweegt toltunnel; haalbaarheidsstudie$$,
   $$economie-vwo-2016-ii-tunnelvisie-context1.png$$,
   $$De Deense overheid overweegt de aanleg en exploitatie van een toltunnel tussen een Deens eiland en het noorden van Duitsland. Hiermee zou de reis- en transporttijd over de weg van bijvoorbeeld Hamburg (Duitsland) naar de Deense hoofdstad Kopenhagen en verder naar Göteborg (Zweden) en Oslo (Noorwegen) gemiddeld een uur korter worden. Ten behoeve van de besluitvorming laat de Deense overheid een financiële haalbaarheidsstudie uitvoeren. De gegevens in onderstaande tabel zijn in miljoenen Deense kroon (DK), tenzij anders aangegeven.$$, 'inline'),
  ('d1f5dc71-bb3f-468b-9f92-e730b13c5d72', 'a01516ce-4b7d-45f1-93a7-df774feb3a94', $$tabel met kosten-, vraag- en opbrengstvergelijkingen van de toltunnel$$,
   $$economie-vwo-2016-ii-tunnelvisie-context2.png$$,
   $$(1) TK = AK + FK + OK | TK = totale kosten per jaar
(2) AK = 0,01Oᵢ | AK = afschrijvingskosten per jaar
(3) FK = 0,03Oᵢ | FK = financieringskosten op de kapitaalmarkt per jaar
(4) OK = 7 | OK = overige kosten per jaar
(5) Oᵢ = 6.000 | Oᵢ = overheidsinvestering voor de tunnel
(6) Qᵥ = −0,5P + 19 | Qᵥ = aantal passages door de toltunnel per jaar in miljoen
(7) P = 18 | P = toltarief in DK per passage inclusief omzetbelasting
(8) TT = P × Q | TT = totale tolopbrengst per jaar
(9) OB = 3Q | OB = overige belastingopbrengsten per jaar
(10) TO = TT + OB | TO = totale opbrengsten per jaar
(11) TR = TO − TK | TR = totale resultaat per jaar$$, 'inline'),
  ('e7f77a94-8171-464c-a3f0-bedffbbb9501', 'a01516ce-4b7d-45f1-93a7-df774feb3a94', $$voorwaarde: totale resultaat per jaar (TR) positief$$,
   $$economie-vwo-2016-ii-tunnelvisie-context3.png$$,
   $$De overheid stelt als voorwaarde voor de aanleg en exploitatie van de toltunnel dat het totale resultaat per jaar (TR) positief moet zijn.$$, 'inline'),
  ('77ef664d-7477-4a25-97c6-3a4b38b95eca', 'a01516ce-4b7d-45f1-93a7-df774feb3a94', $$minister: verhoging toltarief met DK 0,50 verhoogt tolopbrengst$$,
   $$economie-vwo-2016-ii-tunnelvisie-context4.png$$,
   $$De Deense minister van Verkeer onderzoekt mogelijkheden om de aanleg en exploitatie van de tunnel toch haalbaar te maken. Hij komt tot de conclusie dat een verhoging van het toltarief met DK 0,50 per passage de jaarlijkse tolopbrengst uit passages door deze tunnel kan doen toenemen.$$, 'inline'),
  ('3da312c9-c524-4354-87ce-ee93c98f20fa', 'a01516ce-4b7d-45f1-93a7-df774feb3a94', $$minister: belanghebbende partijen laten meebetalen$$,
   $$economie-vwo-2016-ii-tunnelvisie-context5.png$$,
   $$De minister wijst er ook op dat verschillende belanghebbende partijen in binnen- en buitenland in belangrijke mate zullen profiteren van het project. “Ik zie kansen om deze partijen te overtuigen van het belang om financieel deel te nemen.”$$, 'inline'),
  ('3318a2d6-9f05-4fb9-9cb1-932dec1e3844', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$inleiding: geringe groei reëel bbp, lichte inflatie; overheid overweegt investeringen in onderwijs$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context1.png$$,
   $$In een land is sprake van geringe groei van het reële bruto binnenlands product (bbp) in combinatie met een lichte inflatie. De overheid van dit land overweegt een stimulerend beleid door met name overheidsinvesteringen in onderwijs, waarvoor geld geleend zal worden op de kapitaalmarkt. De overheid heeft als doelstelling een zo hoog mogelijke toename van het reële bbp.$$, 'inline'),
  ('3f7891c6-4d06-453e-8c92-ac0634efddc4', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$centrale bank: inflatiedoel 1,8%, onafhankelijk, beïnvloedt rente$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context2.png$$,
   $$De centrale bank (CB) van dit land heeft als doelstelling een stabiel prijspeil: er is voor gekozen dat de inflatie zo weinig mogelijk van 1,8% mag afwijken. In dit land is de CB onafhankelijk van de overheid. De CB kan de rente op de vermogensmarkt beïnvloeden door aanpassingen van het rentetarief waartegen banken bij de CB kunnen lenen.$$, 'inline'),
  ('5ded6739-1a58-46e3-bc19-ac305bd20c9b', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$Bartels geeft situatie weer in een spelboom$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context3.png$$,
   $$Econoom Bartels vraagt zich af welke koers de overheid en de CB zullen varen. Aangezien investeringsbeslissingen voor langere tijd vastliggen en de CB haar beslissingen tussentijds kan wijzigen, heeft Bartels de situatie als volgt in een spelboom weergegeven:$$, 'inline'),
  ('08328cba-5891-4e58-bd32-6cdeb674a726', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$spelboom overheid-centrale bank met stijging reëel bbp en inflatie$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context4.png$$,
   $$spelboom (stijging reële bbp ; inflatie):
Overheid: wel extra overheidsinvesteringen → Centrale bank: rente hoger → 0,5% ; 0,4%
Overheid: wel extra overheidsinvesteringen → Centrale bank: rente gelijk → 1,6% ; 1,4%
Overheid: wel extra overheidsinvesteringen → Centrale bank: rente lager → 2,2% ; 2,4%
Overheid: geen extra overheidsinvesteringen → Centrale bank: rente hoger → -0,9% ; -0,3%
Overheid: geen extra overheidsinvesteringen → Centrale bank: rente gelijk → 0,2% ; 0,7%
Overheid: geen extra overheidsinvesteringen → Centrale bank: rente lager → 1,3% ; 1,7%$$, 'inline'),
  ('8d6b08f4-fb2a-4b1b-bb5e-7a7330ded0a4', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$uitgangssituatie: geen extra investeringen, CB verlaagt rente$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context5.png$$,
   $$In de spelboom staan diverse keuzes van de overheid en de CB, met daarbij de gevolgen van die keuzes. Stel dat in de uitgangssituatie de overheid geen extra investeringen doet. Op basis van de spelboom kan worden geconcludeerd dat de CB de rente dan zal verlagen.$$, 'inline'),
  ('6647ab26-2aa7-4748-8514-76b806b52f0f', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$Bartels: extra investeringen slechts gering effect op reëel bbp$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context6.png$$,
   $$Bartels stelt op basis van de spelboom dat de overheid met het doen van extra investeringen slechts een gering effect kan verwachten op de nagestreefde toename van het reële bbp.$$, 'inline'),
  ('ba72930f-f29c-44c1-9c62-6face5783a86', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$Schiffer: overheid wil nominale bbp zoveel mogelijk laten stijgen$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context7.png$$,
   $$Collega-econoom Schiffer veronderstelt dat de overheid zich vooral laat leiden door kortetermijnreacties van de kiezer. Met de verkiezingen voor de deur wil de overheid het nominale bbp zoveel mogelijk laten stijgen.$$, 'inline'),
  ('2e4b630b-f5c2-4caf-a8b6-c082b400bd75', 'c008d8f2-f2f2-4eaa-8a9c-211561fc963a', $$debat: structurele effecten (Bartels) versus ruilen over de tijd (Schiffer)$$,
   $$economie-vwo-2016-ii-scoren-op-twee-doelen-context8.png$$,
   $$De economen raken in debat over de effecten van overheidsinvesteringen op de langere termijn. Bartels heeft vooral oog voor structurele effecten en verwacht dat deze investeringen in de toekomst tot hogere inkomens zullen leiden. Schiffer benadrukt dat er bij overheidsinvesteringen sprake is van ‘ruilen over de tijd’. Volgens hem zal de burger dit in de toekomst in zijn portemonnee merken.$$, 'inline'),
  ('8393d977-5471-4f24-b0d5-8f47b0f9d9ba', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$inleiding: matchingsites voor verhuur van vakantiehuizen; econoom Tonio$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context1.png$$,
   $$In een land is een markt waarop particulieren hun woning te huur kunnen aanbieden aan toeristen via websites van bemiddelingsbureaus: zogenaamde matchingsites. Geïnteresseerde toeristen kunnen gratis op een matchingsite zoeken in het aanbod van vakantiehuizen en via de matchingsite een huurcontract sluiten. In opdracht van de consumentenorganisatie van dit land bestudeert econoom Tonio deze nieuwe markt. Hij presenteert een aantal gegevens in tabel 1.$$, 'inline'),
  ('dfaaf191-72b6-4742-9f4c-4bbcb24425f6', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$tabel 1: markt van matchingsites (marktaandeel, aanbod, naamsbekendheid, bemiddelingstarieven)$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context2.png$$,
   $$tabel 1 Markt van matchingsites voor verhuur van vakantiehuizen
aanbieder | Sunhouse | Prontocasa | Appartrent
marktaandeel (in % van het aantal transacties) | 60% | 25% | 15%
aandeel aangeboden vakantiehuizen* | 80% | 40% | 40%
naamsbekendheid onder toeristen | 70% | 50% | 50%
bemiddelingstarief voor de aanbieder:
− vast: per ingeschreven vakantiehuis per jaar | 0 euro | 60 euro | 80 euro
− variabel: per geslaagde transactie (in % van de huursom) | 1,8% | 1,0% | 0,8%
*Aantal vakantiehuizen dat op de site van een bepaalde aanbieder te vinden is als percentage van het totaal aantal aangeboden vakantiehuizen$$, 'inline'),
  ('92af8942-444e-431f-a2ca-9f0bcf6c61b0', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$kenmerken van de markt voor onderlinge verhuur$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context3.png$$,
   $$De markt voor onderlinge verhuur vertoont de volgende kenmerken:
− Aanbieders van vakantiehuizen en toeristen kijken bij hun keuze voor een bepaalde matchingsite naar de grootste kans op een geslaagde transactie en naar de laagste kosten.
− De laatste jaren heeft Sunhouse een steeds groter marktaandeel veroverd.
− De matchingsites verschillen in de ogen van toeristen niet in zoekgemak, snelheid en kwaliteit van het assortiment.
− De kosten die de matchingsites maken, bestaan voor het grootste deel uit constante kosten.
− Aanbieders kunnen zich bij meer dan één site inschrijven.$$, 'inline'),
  ('1286b3c9-8f4c-461e-a2a4-c8bdfa6f58de', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$Tonio: laagste bemiddelingstarief hangt af van huursom$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context4.png$$,
   $$Tonio stelt dat het afhangt van de hoogte van de huursom welke matchingsite het laagste totale bemiddelingstarief rekent.$$, 'inline'),
  ('4833fd79-25c1-46dd-8f22-60f876ad92a7', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$Tonio: groeiende naamsbekendheid Sunhouse kan tot monopoliepositie leiden$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context5.png$$,
   $$Tonio voorspelt dat het marktaandeel van Sunhouse verder zal gaan stijgen. Hij redeneert dat hoe groter de naamsbekendheid van Sunhouse bij toeristen wordt, des te meer toeristen de website bezoeken. Dit leidt tot nog meer naamsbekendheid, waarmee Sunhouse nog aantrekkelijker wordt voor aanbieders van vakantiehuizen. Tonio ziet hierin een oorzaak dat Sunhouse een monopoliepositie kan gaan innemen.$$, 'inline'),
  ('a69f0556-c889-4809-ad21-4fca82b7d7c4', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$Tonio: Sunhouse kan concurrenten uit de markt prijzen$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context6.png$$,
   $$Doordat Sunhouse veruit de grootste partij is op de markt, verwacht Tonio dat dit bedrijf de beide concurrenten binnen afzienbare tijd uit de markt kan prijzen.$$, 'inline'),
  ('f27abc2c-3753-443b-801e-5484466d8179', '930fc22c-bc7f-4054-bbf4-f8e1ea921d1e', $$Sonia vreest prijsverhoging; Tonio wijst op makkelijke toetreding$$,
   $$economie-vwo-2016-ii-vakantiehuis-voor-een-zonnig-prijsje-context7.png$$,
   $$Econoom Sonia meent dat zodra Apartrent en Prontocasa uit de markt zijn verdreven, Sunhouse de kans zal aangrijpen om de prijzen snel weer te verhogen. Tonio: “Dat zal zo’n vaart niet lopen. De manier waarop deze bedrijven werken, met alle mogelijkheden van internet, maken toetreding van eventuele nieuwe concurrenten op de markt relatief makkelijk.”$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('346761df-cc69-43ad-8fbb-0a388d2e8578', '935dba97-3b82-406d-a424-ac9c44293f89', 1,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["vraaglijn", "verschuiving vraaglijn", "collectieve vraag", "export", "grafiek aflezen"]'::jsonb,
   $$Uit de verschuiving van de vraaglijn afleiden hoeveel er werd geëxporteerd.$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-vraag1.png$$, $$1p 1 Hoeveel miljoen kilo eieren werden er per maand geëxporteerd voor de export wegviel? Geef de afleiding aan de hand van figuur 1.$$, array['00755628-cce5-47af-babe-3fa106a44cb6', 'b5154f0a-e535-4349-93df-2f1ee86b5664']::uuid[]),
  ('4b657470-9191-435b-86ec-3e917d36b46d', '935dba97-3b82-406d-a424-ac9c44293f89', 2,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["korte termijn", "variabele kosten", "constante kosten", "productie stoppen", "gemiddelde variabele kosten"]'::jsonb,
   $$Beoordelen of een producent bij verlies op korte termijn moet blijven produceren.$$,
   $$economie-vwo-2016-ii-eieren-voor-je-geld-vraag2.png$$, $$2p 2 Zal De Haan in de gegeven situatie op korte termijn stoppen met zijn bedrijf? Licht je antwoord toe, met gebruik van de gegevens.$$, array['51f1307d-238f-40b7-acd9-405e535b3fe4']::uuid[]),
  ('7049cf7f-7a6f-473a-ab24-99460fe77a99', '935dba97-3b82-406d-a424-ac9c44293f89', 3,
